// Optional integration design. Not used or compiled by the default companion.
// Generate and test with a compatible protoc, gRPC plugin, and runtime before use.
syntax = "proto3";
package harbor.dispatch.v1;

service Dispatch {
  rpc Submit(SubmitRequest) returns (SubmitResponse);
  rpc Status(StatusRequest) returns (StatusResponse);
}
message SubmitRequest {
  string key = 1;  // 1..64 ASCII letters, digits, underscore, hyphen.
  int64 input = 2; // 0..1000000. Validate presence/meaning in the adapter policy.
}
message SubmitResponse {
  enum Outcome {
    OUTCOME_UNSPECIFIED = 0;
    ACCEPTED = 1; // Durable intent, not a promise that execution has finished.
    CONFLICT = 2;
    BUSY = 3;
    INVALID = 4;
  }
  Outcome outcome = 1;
  string key = 2;
}
message StatusRequest { string key = 1; }
message Pending { string key = 1; }
message Completed { string key = 1; int64 result = 2; }
message Missing {}
message StatusResponse {
  oneof state {
    Pending pending = 1;
    Completed completed = 2;
    Missing missing = 3;
  }
}
// Transport failures remain gRPC statuses; map domain outcomes intentionally.
// Cancellation does not roll back a committed Submit. Reuse the same key.
// Authentication, tenant scoping, TLS, and server implementation are not supplied
// by this schema. Do not expose the unauthenticated loopback lab publicly.

